C('compare_unit_package_mass','Kiện A có 4 túi bằng nhau, tổng 28 kg. Kiện B có 3 túi bằng nhau, tổng 24 kg. Các túi trong mỗi kiện bằng nhau, chưa nói túi giữa hai kiện bằng nhau. Một túi ở kiện nào nặng hơn.', [('A số túi','4','túi'),('A tổng','28','kg'),('B số túi','3','túi'),('B tổng','24','kg')],'Tìm khối lượng một túi mỗi kiện rồi so sánh.',[S('Một túi A','Các túi A bằng nhau nên rút khối lượng về một túi.',7,'Bốn nhóm7kg có28kg.','28/4','kg'),S('Một túi B','Rút riêng kiện B vì chưa biết đơn vị túi hai kiện bằng nhau.',8,'Ba nhóm8kg có24kg.','24/3','kg'),S('So sánh đơn vị','Cùng là khối lượng của một túi nên so hai kết quả.','Túi B nặng hơn túi A','8kg lớn hơn7kg; tổng kiện A lớn hơn không suy ra mỗi túi A nặng hơn.')],[('Một túi A',7,'kg'),('Một túi B',8,'kg'),('So sánh','Túi B nặng hơn túi A','')]),
C('unit_mass_inverse_bag_count','Bốn bao gạo chứa bằng nhau, tổng 36 kg. Muốn xếp 63 kg gạo vào các bao có khối lượng gạo bằng mỗi bao đã nêu, xếp vừa hết. Cần bao nhiêu bao.', [('Số bao mẫu','4','bao'),('Tổng gạo mẫu','36','kg'),('Tổng cần xếp','63','kg')],'Tìm số bao cần qua khối lượng một bao.',[S('Tìm mỗi bao','Các bao mẫu bằng nhau nên chia để về một bao.',9,'9*4=36kg, khớp mẫu.','36/4','kg'),S('Tìm số bao','Đếm số phần khối lượng bằng một bao trong tổng cần xếp.',7,'7*9=63kg, xếp vừa hết.','63/{s0}','bao')],[('Số bao cần',7,'bao')]),
